class ClientData():
    def __init__(self, data=None, payload=None, error=None):
        self.error = error
        self.data = data
        self.payload = payload

    @property
    def status(self):
        if self.data is None and self.error is None:
            return None

        if self.error is not None:
            return False

        return True
